/**
 * Standard Schema (https://standardschema.dev) v1 interface.
 * Implemented by zod, valibot, arktype and others.
 *
 * @experimental
 */
export interface StandardSchema<Input = unknown, Output = Input> {
  readonly '~standard': {
    readonly version: 1
    readonly vendor: string
