 * The `cause` of the `HTTPException` thrown when a Standard Schema fails.
 *
 * @experimental
 */
export interface ValidationFailure {
  issues: {
    slot: RequestTarget | 'response'
    issues: ReadonlyArray<ValidationIssue>
  }[]
}

