 * Options of `defineHandler()`.
 *
 * @experimental
 */
export type DefineHandlerOptions<E extends Env = any, P extends string = string> = {
  [K in RequestTarget]?: Validation<ValidationTargets[K], E, P>
} & {
  response?: Validation<any, E, P>
}

