  c: Context<E, P, I & OptionsToInput<O>>,
  input: DefineHandlerInput<O>
) => R

type Defined<E extends Env, P extends string, I extends Input, O, R, X> = Handler<
  E,
  P,
  I & OptionsToInput<O>,
  Promise<DefinedResponse<O, R>>
