        } else {
          value = result.value
        }
      } else {
        value = await (responseValidation as Function)(value, c)
        if (value instanceof Response) {
          return value
        }
      }
      return value === undefined ? c.body(null, 204) : c.json(value as object)
    }

    return toResponse(c, value)
  }
